  import { OrderRepository } from '../domain/OrderRepository';
  import { OrderStatus } from '../domain/OrderStatus';
  import { OrderDto } from './dtos';
  import { toOrderDto } from './OrderDtoMapper';

  /** Lists orders, optionally restricted to one state, oldest first. */
  export class ListOrdersUseCase {
    constructor(private readonly orders: OrderRepository) {}

    execute(status?: OrderStatus): OrderDto[] {
      const found = status ? this.orders.findByStatus(status) : this.orders.findAll();
      return found
        .sort((a, b) => a.placedAt.getTime() - b.placedAt.getTime())
        .map(toOrderDto);
    }
  }

  =====SOURCE-END=====

