  import { Clock } from '../domain/Clock';
  import { IdGenerator } from '../domain/IdGenerator';
  import { Order } from '../domain/Order';
  import { OrderRepository } from '../domain/OrderRepository';
  import { Quantity } from '../domain/Quantity';
  import { StockReservationService } from '../domain/StockReservationService';
  import { OrderDto, PlaceOrderInput } from './dtos';
  import { toOrderDto } from './OrderDtoMapper';

  export class PlaceOrderUseCase {
    constructor(
      private readonly orders: OrderRepository,
      private readonly stock: StockReservationService,
      private readonly ids: IdGenerator,
      private readonly clock: Clock,
    ) {}

    execute(input: PlaceOrderInput): OrderDto {
      const lines = input.lines.map((l) => ({ productId: l.productId, quantity: Quantity.of(l.quantity) }));
      const order = Order.place(this.ids.next(), input.customerId, lines, this.clock.now());

      this.stock.reserve(order.lines);
      this.orders.save(order);
      return toOrderDto(order);
    }
  }

